//會員正在搜尋畫面
.member-search {
    width: 305px;
    height: 305px;
    flex-shrink: 0;
    border-radius: 50%;
    background: $white;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 1250;
    position: relative;
    img {
        width: 100px;
    }
    .btn {
        width: 135px;
    }
}
.blockElement {
    z-index: 1200 !important;
}
.dots::after {
    content: "";
    width: 30px;
    display: inline-block;
    text-align: left;
    animation: dots 1.5s infinite;
}

@keyframes dots {
    0% {
        content: "";
    }
    33% {
        content: ".";
    }
    66% {
        content: "..";
    }
    100% {
        content: "...";
    }
}
//會員編輯與新增視窗容器
.member-wrapper {
    overflow-y: auto;
    padding: 0 $w-lg $w-md $w-lg;
    flex: 1 1;
    font-size: $font-xs;
    .form-control {
        font-size: $font-xs;
        border: 1px solid $primary-color;
    }
}
//搜尋與綁定會員視窗
.member-modal {
    .modal-dialog {
        max-width: 980px;
    }
    .message-sign {
        background: $primary-dark-color;
        color: $white;
    }
    .message-icon {
        width: 110px;
        height: 110px;
        background: $primary-xlight-color;
        &[data-con="no"]{
            background: $gray200;
        }
    }
    &-list,&-notice {
        height: calc(100vh - 280px);
    }
    &-notice{
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
    }
    &-title {
        display: flex;
        align-items: center;
        font-size: $font-sm;
        margin-bottom: 12px;
        img {
            width: 20px;
            margin-right: 4px;
        }
    }
    &-line{
        width: 32px;
        display: flex;
        justify-content: center;
        align-items: center;
        flex-shrink: 0;
        position: relative;
            &:after{
            content: "";
            display: block;
            position: absolute;
            width: 1px;
            height: 100%;
            background: $primary-color;
            z-index: 0;
            position: absolute;
            left: 50%;
            top: 0;
        }
        img{
            position: relative;
            z-index: 10;
        }
    }
}
//被選取的會員
.member-pick {
    border-radius: 8px;
    padding: 6px 12px 6px 16px;
    display: flex;
    align-items: center;
    background: $primary-xxlight-color !important;
    text-align: left;
    width: 100%;
    font-weight: $font-bold;
    color: $gray900 !important;
    display: flex;
    margin-bottom: 12px;
    &:last-child{
        margin-bottom: 0;
    }
    &-con {
        display: flex;
    }
    &-tag {
        background: $gray600;
        color: $white !important;
        display: inline-block;
        border-radius: 50px;
        padding: 0 12px;
        font-size: $font-xxs;
    }
    &-point {
        display: flex;
        align-items: center;
        img {
            margin-right: 4px;
            filter: grayscale(100%);
        }
    }
    &-base {
        margin-right: 40px;
    }
    &.active {
        background: lighten($color: $alert-light-color, $amount: 3%) !important;
        color: $white !important;
        &::after {
            content: "";
            display: inline-block;
            flex-shrink: 0;
            width: 30px;
            height: 30px;
            background: url("../images/ic-picked.svg") no-repeat;
        }
        .member-pick-tag {
            background: $alert-color;
        }
        img {
            filter: grayscale(0%);
        }
    }
}
//會員狀態
.member-status {
    height: 38px;
    padding: 12px 8px 12px 16px;
    background: $gray100;
    display: flex;
    align-items: center;
    font-size: $font-xs;
    font-weight: 500;
    button {
        width: 22px;
        height: 22px;
        display: flex;
        justify-content: center;
        align-items: center;
        border-radius: 50%;
        padding: 0;
    }
    &-number {
        background: $gray600;
        color: $white;
        font-size: $font-xxs;
    }
    &>img {
        width: 20px;
    }
}
//會員詳細資料
.member-info{
    border-radius: 24px;
        min-height: 200px;
        display: flex;
        justify-content: center;
        align-items: center;
        position: relative;
        &-photo {
            background: $white;
            border-radius: 50%;
            width: 82px;
            height: 82px;
            display: flex;
            justify-content: center;
            align-items: center;
            background: url("../images/ic-member.svg") no-repeat center $white;
            background-size: 53px;
        }
        &-edit {
            background: $primary-pale-color;
            width: 30px;
            height: 30px;
            border-radius: 50%;
            padding: 4px;
            display: flex;
            justify-content: center;
            align-items: center;
            position: absolute;
            right: 32px;
            bottom: 24px;
        }
}