body {
	font-family:
		Noto Sans TC,
		微軟正黑體;
}

.blockMsg {
	border: 0 !important;
	width: 100px !important;
	height: 100px !important;
	top: calc(50% - 50px) !important;
	left: calc(50% - 50px) !important;
	display: flex !important;
	justify-content: center !important;
	align-items: center !important;
	border-radius: $w-md !important;
}

/*--------------------顧客端畫面開始------------------*/
[data-con="consumer"] {
	.content {
		width: calc(100% - 430px);
		display: flex;
		justify-content: center;
		align-items: center;
		max-height: 100vh;
		padding: 0;
		margin-right: -20px;

		&-video {
			z-index: 0;
			flex-shrink: 1;
			width: 100%;
			background: $black;
			height: calc(100% - 240px);

			&[data-con="videoonly"] {
				height: 100%;
			}

			video {
				width: 100%;
				height: 100%;
			}
		}

		&-img {
			width: 100%;
			height: 100%;
		}

		&-banner {
			width: 100%;
			height: 240px;
			flex-shrink: 0;
		}
	}

	.sidelist {
		width: 450px;
		position: relative;
		z-index: 10;
	}

	.sidebar {
		display: none;
	}

	.sidelist-header {
		background: $primary-color;
		margin-bottom: $w-sm;
		border-radius: $w-md 0 0 0;
		padding: $w-xxs $w-md !important;

		button {
			color: $white !important;

			img {
				filter: brightness(1000%);
			}
		}
	}

	.price-card {
		padding: $w-xs $w-lg $w-sm $w-lg !important;
	}
}

/*--------------------主選單開始------------------*/
.sidebar {
	width: 78px;
	height: 100vh;
	position: relative;
	padding: 48px 0 $w-md 0;
	display: flex;
	flex-direction: column;
	flex-shrink: 0;

	&:before,
	&:after {
		content: "";
		display: block;
		position: absolute;
		width: 24px;
		height: 24px;
		right: -24px;
		background: url("../images/fillet-dark.svg");
		background-size: 100%;
		z-index: 100;
	}

	&:before {
		top: 0;
	}

	&:after {
		bottom: 0;
		transform: rotate(-90deg);
	}

	&-nav {
		flex-shrink: 1;
	}

	&-btn {
		flex-direction: column;
		width: calc(100% - 16px);
		margin-left: $w-xxs;
		padding: $w-xs 0;
		border-radius: $w-md;
	}

	&-logo {
		display: none;
		width: 65%;
		margin: 0 auto;
	}
}

.nav {
	position: relative;

	&-item {
		position: relative;
		z-index: 100;
	}

	&-link {
		display: flex;
		flex-direction: column;
		align-items: center;
		color: $white;
		padding: 20px 0;
		font-variation-settings: $font-bold;
		line-height: 1.2;
		transition: all 0.2s ease;

		&.active {
			margin-left: 8px;
			margin-right: -1px;
			color: $primary-color !important;
			position: relative;

			img {
				filter: invert(45%) sepia(88%) saturate(776%) hue-rotate(173deg) brightness(84%) contrast(90%);
			}
		}

		&:hover,
		&:active,
		&:focus {
			color: $white;
		}

		img {
			width: 28px;
			margin-bottom: 4px;
		}
	}

	&-active {
		border-radius: $w-md 0 0 $w-md;
		background: $white !important;
		position: absolute;
		right: 0;
		top: 10px;
		width: 71px;
		transition: all 0.2s ease;
		z-index: 1;

		&:before,
		&:after {
			content: "";
			display: block;
			position: absolute;
			width: 26px;
			height: 26px;
			right: -2px;
			background: url("../images/fillet-light.svg");
			background-size: 100%;
		}

		&:before {
			top: -24px;
		}

		&:after {
			bottom: -24px;
			transform: rotate(-90deg);
		}
	}
}

/*--------------------內容開始------------------*/
.navbar {
	display: flex;
	justify-content: space-between;
	flex-wrap: nowrap;
	align-items: center;

	&-brand {
		width: 228px;

		h1 {
			font-size: $font-xxl;
		}
	}

	&-info {
		display: flex;
		align-items: center;
		font-variation-settings: $font-bold;

		img {
			width: 20px;
		}
	}
}

.search-input {
	width: 280px;
	position: relative;
	z-index: 200;

	input {
		border-radius: $w-xxxs 0 0 $w-xxxs;
		background: $gray100 !important;
		border: none;
		height: 45px;

		&:focus {
			box-shadow: none;
		}
	}

	input~button {
		border-radius: 0 $w-xxxs $w-xxxs 0 !important;
		background: $gray100 !important;
		border: none;
		height: 45px;

		&:hover {
			img {
				opacity: 0.8;
			}
		}
	}
}

.top-dropdown {
	width: 100%;
	max-width: 125px;

	&-menu {
		border: 1px solid $primary-color;
		color: $primary-color;
		border-radius: 60px;
		background: url("../images/ic-dropdown-pill.svg") right center no-repeat;
		height: 48px;
		display: flex;
		align-items: center;
		padding-left: 16px;
		font-weight: 500;

		&:after {
			display: none;
		}
	}

	&-item {
		border: none;
		padding: 0;
		width: 100% !important;
		min-width: auto;
		display: block;
		/* 必須設為 block 才能跑動畫 */
		/*visibility: hidden;*/
		left: 0;
		top: 50px;
		max-height: 0;
		/* 初始高度為 0 */
		overflow: hidden;
		/* 隱藏溢出內容 */
		transition: all 0.3s ease;

		&.show {
			visibility: visible;
			max-height: 400px;
			/* 給一個足夠大的預估高度 */
		}

		&:before {
			content: "";
			display: block;
			width: 16px;
			height: 16px;
			margin: 4px 16px -12px auto;
			transform: rotate(45deg);
			border-radius: 3px;
			z-index: 0;
			transition: all 0.1s ease;
			background: $primary-color;
		}

		ul {
			background: $white;
			border-radius: $w-xxxs;
			border: 2px solid $primary-color;
			position: relative;
			z-index: 10;
			display: flex;
			flex-direction: column;
			flex-shrink: 0;
			transition: all 0.1s ease;

			li:last-child {
				a {
					&:after {
						display: none;
					}
				}
			}

			a {
				font-family: "Noto Sans TC", "Microsoft JhengHei", "sans-serif";
				font-size: $font-sm;
				color: $gray800;
				padding: $w-xxs $w-xs;
				text-align: center;
				display: block;
				position: relative;

				&:after {
					content: "";
					display: block;
					width: 1px;
					height: 18px;
					right: 0;
					top: 12px;
					position: absolute;
					background: $gray400;
				}

				&:hover {
					color: $gray900;
				}
			}
		}
	}
}

.search-dropdown {
	position: absolute;
	left: 0;
	top: -500px;
	border-radius: $w-xxxs !important;
	box-shadow: 0 0 9px $gray400;
	z-index: 5;
	padding: $w-md $w-md $w-xxs $w-md;
	width: 230px;
	border: 1px solid $gray300;
	transition: all 0.2s ease;
	z-index: 200;

	&.active {
		top: 60px;
	}

	&-item {
		width: 50px;
		height: 50px;
		border-radius: 50% !important;
		background: $gray100;
		padding: 0;
		color: $gray900 !important;
		margin-bottom: $w-sm;
		border: 1px solid $gray100 !important;
		font-size: $font-smd;
		display: flex;
		justify-content: center;
		align-items: center;

		&:hover,
		&:active {
			background: $gray200;
		}

		&[data-con="clear"] {
			background: $white !important;
			font-size: $font-xxs;
			color: $gray800 !important;
		}
	}
}

.content-wrapper {
	display: flex;
	width: 100%;
}

.content {
	padding: $w-sm $w-lg;
	width: calc(100vw - 373px - 78px);

	&[data-con="nodata"] {
		width: calc(100vw - 78px);
	}
}

/*--------------------訂單清單開始------------------*/
.sidelist {
	width: 373px;
	border-radius: $w-md 0 0 $w-md;
	height: 100vh;
	display: flex;
	flex-direction: column;
	flex-shrink: 0;

	&-header {
		flex: 0 0;
		padding: $w-md $w-lg;
	}
}

.sidelist-nav {
	display: block;
	overflow-x: auto;
	height: 36px;
	white-space: nowrap;

	&-item {
		display: inline-block;
		margin-right: 11px;
		vertical-align: top;
		width: calc((100% - calc(#{$w-sm} * 2)) / 3);

		&:last-child {
			margin-right: 0;
		}
	}

	&-link {
		background: $gray200;
		color: $gray900;
		border-radius: 50px;
		width: 100%;
		border: none;

		&.active {
			background: $gray800;
			color: $white;
		}
	}
}

.order-list-wrapper {
	cursor: pointer;
	overflow: auto;
	flex: 1 1;
	padding: 0 $w-lg;
}

.order-list {
	overflow: hidden;
	width: 100%;

	&-item {
		display: flex;
		position: relative;
		left: 0;
		padding: 0 0 $w-sm 0;
		margin-bottom: $w-sm;

		&:after {
			content: " ";
			display: block;
			width: calc(100% + 82px);
			height: 1px;
			background: $gray300;
			position: absolute;
			left: 0;
			bottom: 0;
		}

		&:last-child {
			margin-bottom: 0;

			&:after {
				display: none;
			}
		}
	}

	&-end {
		width: 100px;
		flex-shrink: 0;
		display: flex;
		flex-direction: column;
		justify-content: space-between;
		align-items: flex-end;
	}

	&-img {
		width: 100%;
		border-radius: $w-xxxs;
	}

	&-info {
		width: 100%;

		button[data-style="action"] {
			width: 46px;
			height: 30px;
			padding-left: 0;
			padding-right: 0;

			img {
				width: 20px;
				margin: 0;
			}
		}
	}

	&-title {
		font-size: $font-sm;
		margin-bottom: 4px;
	}

	&-caption {
		font-variation-settings: $font-bold;
	}

	&-txt {
		font-size: $font-xxs;
		color: $gray700;
	}

	&-remove {
		width: 66px;
		background: $danger-color;
		position: absolute;
		top: 0;
		right: -82px;
		color: $white;
		display: flex;
		justify-content: center;
		align-items: center;
		height: calc(100% - #{$w-sm});
	}
}

.number-form {
	display: flex;
	align-items: center;
	justify-content: space-between;
	flex-wrap: nowrap;
	width: 110px;

	button {
		border-radius: $w-xxxs !important;
		padding: 0;
		width: 30px;
		height: 30px;
		display: flex;
		justify-content: center;
		align-items: center;
		flex-shrink: 0;
	}

	div {
		width: 100%;
		cursor: pointer;
		line-height: 30px;
		padding: 0 $w-xxxs;
	}
}

.number-form-ol {
	display: flex;
	align-items: center;
	justify-content: space-between;
	flex-wrap: nowrap;
	width: 110px;
	height: 27px;
	border-radius: $w-xxxs;
	overflow: hidden;
	border: 1px solid $gray600;
	margin-left: 16px;
	margin-right: 16px;
	flex-shrink: 0;
	background: $white;
	color: $gray800;

	&[data-size="lg"] {
		height: 40px;

		div {
			font-weight: 600 !important;
		}

		button {
			width: 48px;
			height: 40px;
		}
	}

	button {
		height: 100%;
		border-radius: 0 !important;
		padding: 0;
		width: 30px;
		height: 30px;
		display: flex;
		justify-content: center;
		align-items: center;
		flex-shrink: 0;
		background: $gray600 !important;
	}

	div {
		width: 100%;
		cursor: pointer;
		line-height: 30px;
		padding: 0 $w-xxxs;
	}

	&[data-style="primary-xlight"] {
		border-color: $primary-xlight-color;
		color: $primary-dark-color;

		button {
			background: $primary-xlight-color !important;

			img {
				filter: invert(49%) sepia(53%) saturate(4618%) hue-rotate(165deg) brightness(66%) contrast(101%);
			}
		}
	}
}

.form-check {
	margin-bottom: 8px;
	padding-bottom: 8px;
	min-height: 36px;

	&:last-child {
		margin-bottom: 0;
	}

	&-input {
		flex-shrink: 0;
	}

	span {
		display: inline-block;
		width: 30px;
		flex-shrink: 0;
	}
}

.form-check:has(input:checked) .number-form-ol {
	border-color: $primary-xlight-color;

	/* 這裡改成你想要的顏色 */
	button {
		background: $primary-xlight-color !important;

		img {
			filter: invert(49%) sepia(53%) saturate(4618%) hue-rotate(165deg) brightness(66%) contrast(101%);
		}
	}
}

.form-check:has(input:disabled) {
	span {
		color: $danger-color !important;
	}
}

.form-check-label {
	margin-right: auto;
}

.price-card {
	font-variation-settings: $font-bold;
	font-size: $font-xs;
	padding: $w-sm $w-lg $w-md $w-lg;
	position: relative;
	flex: 0 0;

	&:before {
		pointer-events: none;
		content: "";
		display: block;
		position: absolute;
		left: 0;
		top: -30px;
		width: 100%;
		height: 30px;
		background: url("../images/scroll-shadow.svg") repeat-x;
	}

	&-item {
		display: flex;
		align-items: center;
		justify-content: space-between;

		&[data-con="total"] {
			border-top: 1px solid $gray300;
			margin-top: $w-xs;
			padding-top: $w-xxxs;
		}
	}

	&-action {
		display: flex;
		justify-content: space-between;

		button {
			width: 100%;
			font-size: $font-md;
			padding: $w-xxs 0;
			border-radius: $w-xxxs !important;
		}
	}

	&-btn {
		display: flex;
		align-items: center;
		color: $primary-color !important;
		font-size: $font-xs;
		font-variation-settings: $font-bold;
		padding: 0;
		border: 0 !important;
	}
}

.price-card-checked {
	padding-bottom: $w-xs;

	.price-card-item {
		&:last-child {
			color: $white !important;
			position: relative;

			p {
				position: relative;
				z-index: 2;
				font-variation-settings: $font-light;
			}

			&::after {
				content: "";
				display: block;
				width: calc(100% + (#{$w-lg} * 2));
				height: calc(100% + #{$w-xs});
				position: absolute;
				left: -32px;
				top: 0;
				background: $primary-color;
				border-radius: 0 0 0 $w-md;
				z-index: 0;
			}
		}
	}
}

.box-list-wrapper {
	flex: 1 1;
	overflow-y: auto;
	padding: 0 $w-lg;
}

.box-list {
	&-item {
		border-radius: $w-xxxs;
		background: $white;
		color: $primary-color;
		width: 100%;
		height: 100%;
		min-height: 80px;
		padding: $w-xs;
		display: flex;
		flex-direction: column;
		justify-content: flex-end;
		align-items: center;

		&:hover,
		&:focus,
		&:first-child:active {
			background: $white;
			color: $primary-color;
		}

		&.active {
			background: $alert-light-color;
			border: 2px solid $white;
			color: $white;

			&:before {
				content: "已選";
				font-size: $font-xxs;
				padding-left: $w-sm;
				color: $white !important;
				background: url("../images/ic-check.svg") no-repeat left center;
			}
		}

		&.disable {
			background: $primary-dark-color;
			color: $white;
			pointer-events: none;
		}

		&[data-bs-target] {
			z-index: 100;

			&.active {
				&::after {
					content: "";
					display: block;
					width: 14px;
					height: 7px;
					background: url("../images/ic-arrow-down.svg") no-repeat;
					background-size: 100%;
					position: absolute;
					left: calc(50% - 6px);
					bottom: -7px;
					z-index: 1;
				}
			}
		}
	}

	&-number {
		font-variation-settings: $font-heavy;
		font-size: $font-md;
	}

	&-text {
		font-variation-settings: $font-bold;
	}

	&-action {
		flex: 0 0;
		padding: 0 $w-lg;

		button {
			font-size: $font-smd;
			border: none;
		}
	}
}

.box-list[data-con="text"] {
	.box-list-item {
		min-height: 54px;
		padding: 0 $w-sm;
		flex-direction: row;
		justify-content: flex-start;
		font-variation-settings: $font-bold;
		position: relative;
		border: 2px solid $white;

		&.active {
			background: $alert-light-color;
			color: $white;
			font-variation-settings: $font-light;

			&:before {
				content: "";
				width: 16px;
				height: 16px;
				display: inline-block;
				background: url("../images/ic-check.svg") no-repeat left center;
			}
		}

		img {
			height: 100%;
			position: absolute;
			right: 0;
			top: 0;
		}
	}
}

.box-list[data-con="number"] {
	.box-list-item {
		min-height: 54px;
		justify-content: center;
		font-variation-settings: $font-bold;
		font-size: $font-md;

		&[data-con="clear"] {
			background: $primary-xlight-color;
			font-size: $font-sm;
		}

		&.active {
			background: $alert-light-color;
			color: $white;
			font-variation-settings: $font-light;
		}
	}

	.box-list-form {
		background: $primary-dark-color !important;
		color: $white !important;
		font-size: $font-lg;
		font-variation-settings: $font-heavy;
		border: 0;
		height: 45px;
		text-align: center;
		letter-spacing: 2px;
		caret-color: transparent;

		&::placeholder {
			color: darken($color: $primary-xlight-color, $amount: 15%) !important;
			font-variation-settings: $font-light;
			letter-spacing: 1px;
		}
	}

	.box-list-form {

		&:-webkit-autofill,
		&:-webkit-autofill:hover,
		&:-webkit-autofill:focus,
		&:-webkit-autofill:active {
			transition: background-color 5000s ease-out 0.5s !important;
			-webkit-text-fill-color: $white !important;
		}
	}
}

.box-list[data-con="number"][data-style="member"] {
	.box-list-form {
		text-align: left;
	}

	.box-list-item {
		min-height: initial;
		height: 48px;
	}
}

/*--------------------視窗開始------------------*/
.backdrop {
	width: 100vw;
	height: 100vh;
	position: absolute;
	left: 0;
	top: 0;
	display: none;
	z-index: 1050;

	&.show {
		display: block;
	}
}

.offcanvas-backdrop.show {
	opacity: 0.2;
}

.offcanvas-header,
.modal-header {
	padding-left: 20px;
	padding-right: 32px;

	.btn {

		&:active,
		&:focus {
			border: 0;
		}
	}
}

.offcanvas-bottom {
	border-radius: $w-md $w-md 0 0;
	height: 412px !important;
	padding: $w-md 0;

	.offcanvas-header {
		position: relative;

		&-close {
			position: absolute;
			background: $gray100 !important;
			border-radius: $w-md $w-md 0 0;
			width: 106px;
			height: 40px;
			top: -39px;
			left: calc(50% - 53px);
			display: flex;
			justify-content: center;
			align-items: center;
			border: none;

			&::before,
			&::after {
				content: "";
				display: block;
				position: absolute;
				width: 24px;
				height: 24px;
				background: url("../images/fillet-gray.svg");
			}

			&::before {
				bottom: -1px;
				left: -23px;
			}

			&::after {
				bottom: -1px;
				right: -23px;
				transform: rotate(90deg);
			}

			&:focus {
				background: $gray100;
			}
		}
	}

	.offcanvas-body {
		padding: 0 66px;
		overflow-y: initial;
	}
