.offcanvas-end {
	width: 373px !important;
	border-radius: $w-md 0 0 $w-md;

	&-lg {
		width: 535px !important;
	}

	.offcanvas-header {
		border-radius: $w-md 0 0 0;
	}
}

.offcanvas-body {
	padding: 0 $w-lg $w-md $w-lg;
}

.modal-header {
	background: $primary-dark-color;
}

.modal-title {
	font-size: $font-sm;
}

.input-text {
	position: relative;
	display: block;

	&::before {
		content: attr(data-txt); // 這裡就能成功抓到 "/"
		position: absolute;
		left: 12px;
		top: 50%;
		transform: translateY(-50%);
		color: $primary-color;
		z-index: 1;
		pointer-events: none; // 讓滑鼠點擊可以穿透到下方的 input
	}

	input {
		padding-left: 24px;
	}
}

.highlight-select {
	overflow: hidden;
	display: flex;
	align-items: center;
	background: rgba($color: $primary-xlight-color, $alpha: .2);

	&-label {
		background: $primary-color;
		color: $white;
		padding: 12px 16px;
		margin-right: 16px;
	}

	.form-check {
		padding-bottom: 0;
		margin-bottom: 0;
	}

	.form-check-inline {
		display: inline-flex;
		align-items: center;
	}

	.form-check-input {
		border: 1px solid $primary-color;
		margin-bottom: 2px;
	}
}

.select-list {
	&-btn {
		display: flex;
		flex-direction: column;
		align-items: center;
		justify-content: space-between;
		width: 100%;
		height: 100%;
		line-height: 1.2;
		padding: $w-xs $w-xs;
		background: $white;
		border: 1px solid $gray200 !important;
		border-radius: $w-xxxs;
		box-shadow: 0 0 9px $gray300;
		transition: all 0 ease;
		position: relative;
		font-size: $font-xsm;
		overflow: hidden;

		&::before {
			background: $white;
			content: " ";
			width: 100%;
			height: 100%;
			position: absolute;
			left: 0;
			top: 0;
			z-index: 0;
			transition: all 0.1s ease;
		}

		&:hover {
			background: $white;
			box-shadow: none;
		}

		&.active {
			background: $primary-color;
			color: $white;
			border: 1px solid $primary-color;
			font-variation-settings: $font-light;

			&::before {
				background: $primary-color;
			}

			p {
				color: $white;
			}

			span {
				color: $white;
				opacity: 0.7;

				&.soldout {
					color: $shine-color;
					opacity: 1;
				}
			}
		}

		&[data-status="soldout"] {
			pointer-events: none;
			box-shadow: none;

			span {
				color: $danger-color;
			}
		}

		p {
			margin-bottom: 4px;
			position: relative;
			z-index: 10;
			color: $gray900;
			font-variation-settings: $font-bold;
		}

		span {
			font-size: $font-xs;
			color: $primary-color;
			position: relative;
			z-index: 10;
			transition: all 0.1s ease;
		}
	}
}

.select-list-wrapper {
	overflow-y: auto;
	padding: 0 $w-lg $w-md $w-lg;
	flex: 1 1;
	font-size: $font-xxs;

	.form-check-input {
		width: $w-sm;
		height: $w-sm;
		margin-top: 0;
		border: 2px solid $gray700 !important;

		&[type="radio"] {
			border-radius: 50%;
		}

		&:checked[type="radio"] {
			border-radius: 50%;
			background: url(../images/radio-circle.svg) no-repeat center $primary-color;
			background-size: 6px;
			border: 2px solid $primary-color !important;
		}

		&[type="checkbox"] {
			border-radius: $w-xxxs;
		}

		&:checked[type="checkbox"] {
			background: url(../images/ic-check.svg) no-repeat center $primary-color;
			background-size: 9px;
			border: 2px solid $primary-color !important;
		}
	}

	input[disabled] {
		border: 2px solid $gray600;
	}

	input[disabled]~label {
		opacity: 1 !important;
		color: $gray700;
	}

	label {
		display: flex;
		justify-content: space-between;
		padding-left: $w-xxxs;

		p {
			display: block;
			width: calc(100% - 70px);
			flex: 1 1;
			line-height: 1.3;
		}

		span {
			padding-left: $w-xxs;
		}
	}
}

.modal {
	&-content {
		background: $primary-color;
		border-radius: $w-md;
		overflow: hidden;
	}

	&-header {
		border: 0;
		color: $white;
		display: flex;
		justify-content: center;
		position: relative;

		button {
			position: absolute;
			right: 10px;

			&:focus,
			&:active {
				border: none !important;
			}
		}
	}

	&-body {
		background: $white;
		font-size: $font-smd;
		min-height: 100px;
		display: flex;
		justify-content: center;
		align-items: center;
	}

	&-footer {
		background: $white;
		border: 0;
		display: flex;
		justify-content: center;

		&>* {
			width: 130px;
			margin: 0;
			flex-shrink: 1;
		}
	}

	&-action {
		border-radius: $w-xxxs;
		letter-spacing: 2px;
		max-width: 200px;
	}
}

.checkout {
	display: flex;
	justify-content: space-between;
	align-items: stretch;
	height: 100%;
	overflow: hidden;
	padding: 8px 0;

	&[data-con="has-receipt"] {
		.checkout-receipt {
			display: block;
		}

		.checkout-sum-item {
			p:first-child {
				font-size: $font-sm !important;
			}

			p:last-child {
				font-size: $font-lg !important;
			}
		}

		.checkout-sum-list {
			padding-bottom: 0;
		}
	}

	&-pay {
		width: 241px;
		flex-shrink: 0;
		margin-right: $w-md;
		display: flex;
		flex-direction: column;
		justify-content: space-between;
		height: 100%;

		li {
			height: calc(33.33% - 6px);
		}

		&-item {
			display: flex;
			height: 100%;
			align-items: center;
			padding: 0 $w-md;
			background: $white;
			color: $primary-color;
			border-radius: $w-xxxs;
			box-shadow: 0 0 9px $gray300;
			transition: all 0.2s ease;
			position: relative;
			font-size: $font-smd;
			border: 1px solid $gray300;

			&:hover {
				color: $primary-color;
				box-shadow: none;
			}

			&:after {
				content: "";
				display: block;
				position: absolute;
				right: 10px;
				bottom: calc(50% - 9px);
				width: 16px;
				height: 16px;
				background: $white;
				border-radius: 3px;
				transform: rotate(45deg);
				z-index: 1;
				transition: all 0.2s ease;
			}

			&.active {
				background: $primary-color;
				color: $white;
				border: 1px solid $primary-color;

				&:after {
					background: $primary-color;
					right: -6px;
				}

				img {
					filter: invert(100%) sepia(100%) saturate(0%) hue-rotate(330deg) brightness(300%) contrast(104%);
				}
			}
		}
	}

	&-coupon {
		width: 86px;
		margin-right: 20px;
		flex-shrink: 0;
		position: relative;
		transition: all 0.2s ease;
		overflow: hidden;

		&.active {
			margin-right: 12px;
		}

		// 只用目前 active 狀態決定容器寬度
		&.active:has(.checkout-coupon-list.active) {
			width: 442px;
		}

		&.active:has(.checkout-point-list.active) {
			width: 300px;
		}


		&.hide {
			display: none;
		}

		&-toggler {
			width: 86px;
			height: 100%;
			margin-right: 24px;
			display: flex;
			flex-direction: column;
			align-items: center;
			font-size: $font-smd;
			line-height: 1.2;
			position: relative;
			border-radius: $w-xxxs;
			z-index: 10;

			&[data-con="point"] {
				&::after {
					background: $alert-light-color;
				}

				img {
					filter: none;
				}
				&.active,
				&:focus {
					background: $alert-light-color !important;
					&:after {
						background: $alert-light-color;
						right: -6px;
					}
				}
				&.using {
					border: 2px solid $alert-light-color !important;
					color: $alert-light-color !important;
					img{
						filter: invert(57%) sepia(78%) saturate(666%) hue-rotate(337deg) brightness(130%) contrast(100%);
					}
			}
				
			}

			&:after {
				content: "";
				display: block;
				position: absolute;
				right: 2px;
				bottom: calc(50% - 9px);
				width: 16px;
				height: 16px;
				border-radius: 3px;
				transform: rotate(45deg);
				z-index: 1;
				transition: all 0.2s ease;
				background: $danger-light-color;
			}

			&:hover {
				&:after {
					background: darken($color: $danger-light-color, $amount: 5%);
				}
			}

			&.active,
			&:focus {
				background: $danger-light-color !important;

				&:after {
					background: $danger-light-color;
					right: -6px;
				}
			}

			&.using {
				background: $white !important;
				border: 2px solid $danger-light-color;
				color: $danger-light-color !important;

				&:after {
					background: $white;
					right: 2px;
				}

				img {
					filter: none;
				}
			}

			img {
				filter: invert(100%) sepia(70%) saturate(0%) hue-rotate(216deg) brightness(500%) contrast(100%);
				margin-bottom: 4px;
			}
		}

		&-list {
			position: absolute;
			width: 340px;
			height: calc(100% + 8px);
			left: -373px;
			padding: 8px 8px 0 8px;
			top: -8px;
			z-index: 0;
			overflow: auto;
			justify-content: flex-start;
			flex-direction: column;
			flex-wrap: nowrap;

			&.active {
				left: auto;
				right: 0;
			}
		}
	}

	&-point {
		&-list {
			position: absolute;
			width: 200px;
			height: calc(100% + 8px);
			left: -250px;
			padding: 8px 8px 0 8px;
			top: -8px;
			z-index: 0;
			overflow: auto;
			justify-content: flex-start;
			flex-direction: column;
			flex-wrap: nowrap;

			&.active {
				left: auto;
				right: 0;
			}
		}
	}

	&-keyboard {
		width: 510px;
		margin-right: 20px;
		height: 100%;
		flex-shrink: 0;

		&-list {
			margin: 0 auto;

			&[data-con="pay-service"] {
				.checkout-keyboard-list-item {
					background: $white;

					&:hover {
						box-shadow: none;
					}
				}
			}

			&-item {
				width: 100%;
				height: 100%;
				font-size: $font-xl;
				box-shadow: 0 3px 8px $gray400;
				border: 0;

				&:hover {
					box-shadow: none;
				}
			}
		}

		&-form {
			width: 100%;
			max-width: 520px;
			margin: 0 auto;
			padding: 0 3px;

			&-input {
				text-align: center;
				color: $gray800;
				font-variation-settings: $font-heavy;
				font-size: $font-xl;
				letter-spacing: 3px;
				position: relative;
				border-radius: $w-xxxs;
			}

			&-label {
				position: absolute;
				left: $w-md;
				top: 0;
				color: $gray700;
				z-index: 10;
				height: 56px;
				line-height: 56px;
				font-size: $font-smd;
				font-variation-settings: $font-bold;
				background: none;
			}
		}
	}

	&-end {
		display: flex;
		flex-direction: column;
		flex-shrink: 0;
		width: 315px;
	}

	&-receipt {
		display: none;
		flex-shrink: 0;

		input {
			pointer-events: none;
		}

		.basic-input-group {
			cursor: pointer;
		}

		.basic-input-group.active {
			span {
				background: $alert-color !important;
			}

			input {
				border-color: $alert-color !important;
			}
		}
	}

	&-sum {
		display: flex;
		flex-direction: column;
		height: 100%;

		&-list {
			display: flex;
			justify-content: space-between;
			flex-direction: column;
			flex-grow: 1;
			padding-bottom: 12px;
		}

		&-item {
			display: flex;
			align-items: center;
			justify-content: space-between;

			&:last-child {
				margin-bottom: 0;
			}
		}

		&-unlock {
			flex-shrink: 0;
		}
	}
}

